alter table public.knowledge_article_versions add column submitted_at timestamptz, add column approved_at timestamptz, add column approved_by uuid references public.user_profiles(id) on delete set null;
create or replace function public.submit_knowledge_article_review(target_article_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare article public.knowledge_articles%rowtype; begin select * into article from public.knowledge_articles where id=target_article_id for update; if article.id is null or not public.has_organization_role(article.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'KNOWLEDGE_NOT_AUTHORIZED'; end if; if article.status<>'DRAFT' then raise exception 'KNOWLEDGE_INVALID_STATE'; end if; update public.knowledge_article_versions set submitted_at=clock_timestamp() where article_id=article.id and version_number=article.current_version; update public.knowledge_articles set status='IN_REVIEW' where id=article.id; insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(article.organization_id,auth.uid(),'KNOWLEDGE_ARTICLE_SUBMITTED','knowledge_article',article.id,jsonb_build_object('version',article.current_version),'WEB'); end; $$;
create or replace function public.approve_knowledge_article(target_article_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare article public.knowledge_articles%rowtype; version_record public.knowledge_article_versions%rowtype; begin select * into article from public.knowledge_articles where id=target_article_id for update; select * into version_record from public.knowledge_article_versions where article_id=target_article_id and version_number=article.current_version for update; if article.id is null or not public.has_organization_role(article.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'KNOWLEDGE_NOT_AUTHORIZED'; end if; if article.status<>'IN_REVIEW' or version_record.submitted_at is null then raise exception 'KNOWLEDGE_NOT_IN_REVIEW'; end if; if version_record.created_by=auth.uid() then raise exception 'KNOWLEDGE_SELF_APPROVAL_FORBIDDEN'; end if; update public.knowledge_article_versions set approved_at=clock_timestamp(),approved_by=auth.uid() where id=version_record.id; update public.knowledge_articles set status='PUBLISHED' where id=article.id; insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(article.organization_id,auth.uid(),'KNOWLEDGE_ARTICLE_PUBLISHED','knowledge_article',article.id,jsonb_build_object('version',article.current_version),'WEB'); end; $$;
revoke all on function public.submit_knowledge_article_review(uuid),public.approve_knowledge_article(uuid) from public; grant execute on function public.submit_knowledge_article_review(uuid),public.approve_knowledge_article(uuid) to authenticated;
